p='helpers/consts.ts'
s=open(p).read()
s=s.replace('  InngestDevMode = "INNGEST_DEV",\n','  InngestDevMode = "INNGEST_DEV",\n  InngestSessionPropagation = "INNGEST_SESSION_PROPAGATION",\n',1)
open(p,'w').write(s)
p='components/Inngest.ts'
s=open(p).read()
s=s.replace('''export const internalLoggerSymbol = Symbol.for("inngest.internalLogger");
''','''export const internalLoggerSymbol = Symbol.for("inngest.internalLogger");

/**
 * Symbol for accessing whether session propagation is enabled. Not part of the
 * public API.
 * @internal
 */
export const sessionPropagationSymbol = Symbol.for(
  "inngest.sessionPropagation",
);
''',1)
s=s.replace('''  get mode(): Mode {''','''  /**
   * Whether session propagation is enabled. Resolved lazily from the current
   * env so that vars supplied via `setEnvVars` are honoured.
   *
   * @internal
   */
  get [sessionPropagationSymbol](): boolean {
    return (
      parseAsBoolean(this._env[envKeys.InngestSessionPropagation]) ?? false
    );
  }

  get mode(): Mode {''',1)
open(p,'w').write(s)
E
cd ..; npx tsc --noEmit -p . 2>&1 | head

